import { useState } from "react";

export function InvoiceForm({ submitInvoice }: { submitInvoice: () => Promise<void> }) {
  const [error, setError] = useState("");
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    try { await submitInvoice(); } catch { setError("Invoice not sent: the client email is missing. Add it under Billing contact."); }
  }
  return (
    <form onSubmit={handleSubmit}>
      {error && <p role="alert">{error}</p>}
      <button type="submit">Send invoice</button>
    </form>
  );
}

